declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/Support/EquipmentFactsFixture.php';
$migrationSource=file_get_contents(dirname(__DIR__,2).'/app/InstallationProcess/EquipmentFactsSchemaMigration.php');foreach(['information_schema.COLUMNS','information_schema.STATISTICS','information_schema.CHECK_CONSTRAINTS','information_schema.TRIGGERS','TABLE_COLLATION']as$manifestPart)assertSameValue(true,str_contains($migrationSource,$manifestPart),'compatibility validates full schema manifest '.$manifestPart);
use FMonitor2\InstallationProcess\{EquipmentFactsSchemaMigration,ProductionPilotMigrationCatalogue};use FMonitor2\RuntimeRestore\{RuntimeRecoverySchemaV30,RuntimeRecoverySchemaV31,RuntimeRecoverySchemaV32};assertSameValue(true,class_exists(EquipmentFactsSchemaMigration::class),'INTENDED_RED schema migration missing');
function efSchema(mysqli$db,string$table):array{$s=$db->prepare("SELECT COLUMN_NAME,LOWER(COLUMN_TYPE) type,IS_NULLABLE,COLUMN_DEFAULT,EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? ORDER BY ORDINAL_POSITION");$s->execute([$table]);$columns=array_map(static function(array$r):array{if($r['IS_NULLABLE']==='YES'&&$r['COLUMN_DEFAULT']==='NULL')$r['COLUMN_DEFAULT']=null;return array_values($r);},$s->get_result()->fetch_all(MYSQLI_ASSOC));$s=$db->prepare("SELECT INDEX_NAME,NON_UNIQUE,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? GROUP BY INDEX_NAME,NON_UNIQUE");$s->execute([$table]);$indexes=array_map(static fn(array$r):array=>[(string)$r['INDEX_NAME'],(string)$r['NON_UNIQUE'],(string)$r['cols']],$s->get_result()->fetch_all(MYSQLI_ASSOC));usort($indexes,static fn(array$a,array$b):int=>($a[0]==='PRIMARY'?-1:($b[0]==='PRIMARY'?1:strcmp($a[0],$b[0]))));$s=$db->prepare("SELECT COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? AND REFERENCED_TABLE_NAME IS NOT NULL ORDER BY COLUMN_NAME");$s->execute([$table]);$foreign=array_map('array_values',$s->get_result()->fetch_all(MYSQLI_ASSOC));$s=$db->prepare("SELECT LOWER(REPLACE(REPLACE(CHECK_CLAUSE,'`',''),' ','')) clause FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE()AND TABLE_NAME=? ORDER BY clause");$s->execute([$table]);$checks=array_column($s->get_result()->fetch_all(MYSQLI_ASSOC),'clause');$checks=array_map(static fn(string$x):string=>str_replace('!(','not(',$x),$checks);sort($checks,SORT_STRING);return[$columns,$indexes,$foreign,$checks];}
$f=new EquipmentFactsFixture('schema');try{$first=EquipmentFactsSchemaMigration::apply($f->db,$f->p);$second=EquipmentFactsSchemaMigration::apply($f->db,$f->p);assertSameValue([true,false],[$first['applied'],$second['applied']],'additive/idempotent migration');$expected=['fm2_equipment_fact_current'=>[[['object_id','bigint(20) unsigned','NO',null,''],['readiness_date','date','YES',null,''],['first_shipment_date','date','YES',null,''],['full_shipment_date','date','YES',null,''],['source','varchar(20)','NO',null,''],['source_order_hmac','char(64)','NO',null,''],['last_successful_run_id','char(36)','NO',null,''],['last_successful_observed_at','datetime(6)','NO',null,'']],[['PRIMARY','0','object_id'],['last_success','1','last_successful_observed_at']],[],["source='1c_erp'","source_order_hmacregexp'^[0-9a-f]{64}$'"]],'fm2_equipment_fact_history'=>[[['id','bigint(20) unsigned','NO',null,'auto_increment'],['object_id','bigint(20) unsigned','NO',null,''],['fact_type','varchar(24)','NO',null,''],['old_value','date','YES',null,''],['new_value','date','YES',null,''],['source','varchar(20)','NO',null,''],['source_order_hmac','char(64)','NO',null,''],['run_id','char(36)','NO',null,''],['observed_at','datetime(6)','NO',null,'']],[['PRIMARY','0','id'],['object_history','1','object_id,id'],['run_fact','1','run_id,fact_type']],[],["fact_typein('readiness','first_shipment','full_shipment')","not(old_value<=>new_value)","source='1c_erp'","source_order_hmacregexp'^[0-9a-f]{64}$'"]],'fm2_equipment_fact_runs'=>[[['run_id','char(36)','NO',null,''],['command_hash','char(64)','NO',null,''],['kind','varchar(16)','NO',null,''],['status','varchar(16)','NO',null,''],['reason','varchar(40)','YES',null,''],['observed_at','datetime(6)','NO',null,''],['receipt_json','longtext','NO',null,''],['created_at','datetime(6)','NO',null,'']],[['PRIMARY','0','run_id'],['observed_status','1','observed_at,status']],[],["command_hashregexp'^[0-9a-f]{64}$'","json_valid(receipt_json)","kindin('complete','failed')","statusin('completed','failed')"]],'fm2_equipment_fact_sync_metadata'=>[[['singleton_id','tinyint(3) unsigned','NO',null,''],['last_successful_run_id','char(36)','YES',null,''],['last_successful_observed_at','datetime(6)','YES',null,''],['latest_failure_reason','varchar(40)','YES',null,''],['latest_failure_observed_at','datetime(6)','YES',null,'']],[['PRIMARY','0','singleton_id']],[],['singleton_id=1']],'fm2_equipment_fact_diagnostics'=>[[['id','bigint(20) unsigned','NO',null,'auto_increment'],['run_id','char(36)','NO',null,''],['source_order_hmac','char(64)','NO',null,''],['reason','varchar(40)','NO',null,''],['created_at','datetime(6)','NO',null,'']],[['PRIMARY','0','id'],['run_reason','1','run_id,reason']],[],["reasonin('object_not_found','object_ambiguous')","source_order_hmacregexp'^[0-9a-f]{64}$'"]]];foreach($expected as$table=>$manifest)assertSameValue($manifest,efSchema($f->db,$f->p.$table),'exact columns/keys/FKs/checks '.$table);assertSameValue([1],array_map('intval',array_column($f->rows('fm2_equipment_fact_sync_metadata'),'singleton_id')),'singleton metadata row');$f->db->query("INSERT INTO {$f->p}fm2_equipment_fact_runs VALUES('11111111-1111-4111-8111-111111111111','".str_repeat('a',64)."','complete','completed',NULL,'2026-09-15 12:00:00.000000','{}','2026-09-15 12:00:00.000000')");$f->db->query("INSERT INTO {$f->p}fm2_equipment_fact_history(object_id,fact_type,old_value,new_value,source,source_order_hmac,run_id,observed_at)VALUES(1,'readiness',NULL,'2026-09-01','1c_erp','".str_repeat('b',64)."','11111111-1111-4111-8111-111111111111','2026-09-15 12:00:00.000000')");foreach(['UPDATE '.$f->p."fm2_equipment_fact_history SET new_value='2026-09-02' WHERE id=1",'DELETE FROM '.$f->p.'fm2_equipment_fact_history WHERE id=1']as$sql)try{$f->db->query($sql);throw new TestFailure('append-only history mutation accepted');}catch(mysqli_sql_exception$e){assertSameValue(true,str_contains($e->getMessage(),'EQUIPMENT_FACT_HISTORY_APPEND_ONLY'),'append-only DB enforcement');}$catalog=file_get_contents(dirname(__DIR__,2).'/app/InstallationProcess/ProductionPilotMigrationCatalogue.php');assertSameValue(true,str_contains($catalog,'EquipmentFactsSchemaMigration'),'production catalogue registration');assertSameValue(true,class_exists(RuntimeRecoverySchemaV31::class),'recovery v31 exists');$added=array_values(array_diff(RuntimeRecoverySchemaV31::tables($f->p),RuntimeRecoverySchemaV30::tables($f->p)));sort($added);$owned=array_map(fn($x)=>$f->p.$x,array_keys($expected));sort($owned);assertSameValue($owned,$added,'backup exact owned inventory');assertSameValue(31,RuntimeRecoverySchemaV31::VERSION,'backup schema version');assertSameValue(true,str_contains(file_get_contents(dirname(__DIR__,2).'/app/RuntimeRestore/RuntimeRecovery.php'),'RuntimeRecoverySchemaV32'),'runtime backup/restore uses current v32');$f->db->query("DROP TABLE {$f->p}fm2_equipment_fact_diagnostics");$f->db->query("CREATE TABLE {$f->p}fm2_equipment_fact_diagnostics(bad INT)");try{EquipmentFactsSchemaMigration::apply($f->db,$f->p);throw new TestFailure('incompatible table accepted');}catch(RuntimeException$e){assertSameValue('SCHEMA_MIGRATION_CONFLICT',$e->getMessage(),'fail closed recovery');}echo"PASS: ERP-EQUIPMENT-FACTS-001 schema/recovery\n";}finally{$f->close();}
